        "text": "y＝−2xの直線が右下がりになる理由を説明しよう。 図の角度だけで比例定数を決めてよい？ 比例定数が−2なので右へ1進むごとに下へ2進む。軸の尺度で見た角度が変わるため、座標の商で確かめる。 確認項目：xが1増えるとyが2減ると説明した。 / 尺度を確認し座標から商を求めると説明した。",
