        "text": "接線の作図に垂線の作図が使える理由は？ 半径は円のどの点へ引いてもよい？ 接線は接点を通る半径と垂直だから、その点での垂線を作ればよい。別の点への半径では条件が違う。 確認項目：接点で半径と接線が垂直と説明した。 / 接点へ向かう半径を使うと特定した。",
