        "text": "円上の点Pで接線を作図しよう。 円の中心Oと接点Pを結び、半径OPを引く。 Pを通るOPへの垂線を、基本作図で作る。 作った直線と半径の角が90°であることを確認する。 その直線は円にPだけで接するので接線である。 結論：Pを通る半径OPへの垂線",
