        "detail": "直方体の一つの底辺と、別の角の縦の辺を考える。延長しても交わらず、向きも平行でない組はねじれの位置。紙に描いた線が交差して見えても、空間で同じ点を通るとは限らない。直線が平面に垂直というときは、その交点を通る平面内の交わる二直線へ垂直かを確かめる。一本だけへの直角では足りない。"
